<details class="panel composer" <?=$dashboard['total']===0?'open':''?>><summary><span class="icon-tile"><?=admin_icon('chart')?></span><span><strong>Create a poll</strong><small>One question. A voice for every player.</small></span><span class="summary-action">New poll +</span></summary>
<form method="post" class="composer-body"><?php admin_csrf()?><input type="hidden" name="action" value="poll_create"><label>Question<input name="question" required maxlength="160" placeholder="What should we work on next?"></label><div class="poll-options"><?php for($i=1;$i<=6;$i++):?><label>Option <?=$i?> <?=$i>2?'<span class="optional">Optional</span>':''?><input name="options[]" maxlength="80" <?=$i<=2?'required':''?> placeholder="Answer choice <?=$i?>"></label><?php endfor?></div>
<div class="duration-row"><label>Voting duration<input name="duration" type="number" min="1" max="43200" value="24" required></label><label>Unit<select name="unit"><option value="minutes">Minutes</option><option value="hours" selected>Hours</option><option value="days">Days</option></select></label></div><div class="form-footer"><p>1 minute to 30 days · 2–6 choices · One vote per account.<br>Questions and choices are fixed after publishing.</p><button class="primary">Publish poll <?=admin_icon('arrow')?></button></div></form></details>
<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="polls"><label>Poll status<select name="state"><option value="">All polls</option><option value="open" <?=$dashboard['state']==='open'?'selected':''?>>Open</option><option value="ended" <?=$dashboard['state']==='ended'?'selected':''?>>Ended</option></select></label><button>Apply filter</button><span class="filter-count"><?=h((string)$dashboard['total'])?> poll(s)</span></form></section>
<?php if(!$dashboard['polls']):?><section class="panel empty-state"><?=admin_icon('chart')?><h2>No polls here yet.</h2><p>Create a poll above to hear from your community.</p></section><?php endif?>
<?php foreach($dashboard['polls'] as $poll):$active=!(int)$poll['closed']&&(int)$poll['closes_at']>time();?><article class="panel" id="poll-<?=h((string)$poll['id'])?>"><div class="panel-heading"><div><span class="eyebrow">POLL #<?=h((string)$poll['id'])?></span><h2><?=h($poll['question'])?></h2></div><span class="badge <?=$active?'success':'muted'?>"><?=$active?'Open':'Ended'?></span></div><div class="poll-meta"><span><strong><?=h((string)$poll['total'])?></strong> total votes</span><span>Closes <?=h(gmdate('d M Y, H:i',(int)$poll['closes_at']))?> UTC</span></div>
<?php foreach($poll['results'] as $result):$percent=$poll['total']?round((int)$result['votes']*100/$poll['total'],1):0;?><div class="poll-result"><span><?=h($result['label'])?></span><strong><?=h((string)$percent)?>% <small>· <?=h((string)$result['votes'])?> votes</small></strong><progress value="<?=h((string)$result['votes'])?>" max="<?=max(1,$poll['total'])?>" aria-label="<?=h($result['label'])?>"></progress></div><?php endforeach?>
<?php if($active):?><form method="post" class="close-poll"><?php admin_csrf()?><input type="hidden" name="action" value="poll_close"><input type="hidden" name="poll_id" value="<?=h((string)$poll['id'])?>"><button>Close voting early</button><span class="hint">Results will be retained.</span></form><?php endif?>
<details class="danger-zone"><summary>Delete poll</summary><p>This permanently removes the poll and all its results.</p><form method="post"><?php admin_csrf()?><input type="hidden" name="action" value="poll_delete"><input type="hidden" name="poll_id" value="<?=h((string)$poll['id'])?>"><button class="danger">Delete poll and results</button></form></details></article><?php endforeach?>
<?php admin_pagination($dashboard,'polls',['state'=>$dashboard['state']])?>
